# PySpark Delta Table SCD2 MERGE pattern
from delta.tables import DeltaTable
target = DeltaTable.forName(spark, 'silver.dim_customer')
# Split staging into inserts and historical closes
staged = staged_updates.selectExpr('NULL as merge_key', 'updates.*') \
  .union(staged_updates.selectExpr('customer_id as merge_key', 'updates.*'))
target.alias('t').merge(
    staged.alias('s'),
    't.customer_id = s.merge_key AND t.is_current = true'
).whenMatchedUpdate(
    condition='t.address <> s.address',
    set={'is_current': 'false', 'end_date': 's.effective_date'}
).whenNotMatchedInsert(
    values={'customer_id': 's.customer_id', 'address': 's.address', 'is_current': 'true', 'effective_date': 's.effective_date', 'end_date': 'NULL'}
).execute()

